"use client";
/* Sushi, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Sushi(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("sushi"); }, []);
  return React.createElement("piix-sprite", { "name": "sushi", ...piixAttrs(props) });
}

export default Sushi;
